#include <cmath>
using namespace std;

int main() {
    long long l, r, x, y;
    cin >> l >> r >> x >> y;

    // For GCD(a,b) = x and LCM(a,b) = y, we must have x | y
    if (y % x != 0) {
        cout << 0 << endl;
        return 0;
    }

    long long n = y / x;

    // a = x * a', b = x * b' where GCD(a', b') = 1 and LCM(a', b') = n
    // So a' * b' = n and GCD(a', b') = 1
    // This means a' and b' are coprime and their product is n.
    // So a' and b' must be formed by partitioning the prime factors of n.
    // For each prime power p^k in n, it must go entirely to a' or entirely to b'.

    // First, check if a and b can be in range [l, r]
    // a = x * a', b = x * b'
    // We need l <= x * a' <= r and l <= x * b' <= r
    // So a' must be in [ceil(l/x), floor(r/x)]

    long long min_a_prime = (l + x - 1) / x; // ceil(l/x)
    long long max_a_prime = r / x;            // floor(r/x)

    if (min_a_prime > max_a_prime) {
        cout << 0 << endl;
        return 0;
    }

    // Factorize n
    vector<pair<long long, int>> factors;
    long long temp = n;
    for (long long p = 2; p * p <= temp; p++) {
        if (temp % p == 0) {
            int cnt = 0;
            while (temp % p == 0) {
                cnt++;
                temp /= p;
            }
            factors.push_back({p, cnt});
        }
    }
    if (temp > 1) {
        factors.push_back({temp, 1});
    }

    // Number of ways to assign each prime power to a' or b' is 2^(number of distinct primes)
    // But we need to count pairs (a', b') such that a' * b' = n, GCD(a', b') = 1
    // and both a' and b' are in [min_a_prime, max_a_prime]

    // Generate all divisors of n that are "squarefree-like" in the sense that they contain full prime powers
    // Actually, a' must be a divisor of n such that for each prime p^k || n, either p^k divides a' or p doesn't divide a'
    // So a' is of the form product of some subset of {p_i^{k_i}}

    int num_primes = factors.size();
    long long total_ways = 1LL << num_primes;

    long long count = 0;
    for (long long mask = 0; mask < total_ways; mask++) {
        long long a_prime = 1;
        for (int i = 0; i < num_primes; i++) {
            if (mask & (1 << i)) {
                long long p = factors[i].first;
                int k = factors[i].second;
                for (int j = 0; j < k; j++) {
                    a_prime *= p;
                }
            }
        }
        long long b_prime = n / a_prime;

        // Check if both are in range
        if (a_prime >= min_a_prime && a_prime <= max_a_prime && 
            b_prime >= min_a_prime && b_prime <= max_a_prime) {
            count++;
        }
    }

    cout << count << endl;
    return 0;
}
